package org.example.examples.shopping.data.coordination

import rocky.CommandRuntime
import rocky.ServiceCoordinator

/**
 * The trust bundle of the public coordination service the app orders its approvals with (`PUBLIC_COORDINATOR.md` at
 * the checkout root). It pins the provider's root, mesh and certified genesis; the service learns request
 * identities and commitments, never requests, rows or keys. See docs/runtime/public-coordination.md.
 */
const val PUBLIC_COORDINATOR_BUNDLE: String =
    """{"format":1,"root":"4302b557f51216062ff616dc0246f5d7bcf3f04102c7d42e9f222a5113fdebd6","mesh":[82,75,123,115,236,16,26,168,49,219,79,195,227,114,235,226],"genesis":""}"""

/** Strong commands through the public service, with the approval handlers; trusted devices execute them. */
fun publicCoordination(): CommandRuntime = CommandRuntime(ServiceCoordinator(PUBLIC_COORDINATOR_BUNDLE), ApprovalHandlers)
